begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok((select not rolcanlogin and not rolinherit and not rolbypassrls and not rolsuper from pg_roles where rolname='carrier_finance'),'Finance owner cannot log in or bypass RLS');
select ok(not pg_has_role('authenticated','carrier_finance','MEMBER') and not pg_has_role('anon','carrier_finance','MEMBER') and not pg_has_role('postgres','carrier_finance','SET'),'Finance role cannot be assumed by clients or migration administrator');
select ok(not has_schema_privilege('carrier_finance','public','CREATE') and not has_schema_privilege('carrier_finance','private','CREATE'),'Finance cannot replace functions');
select ok((select bool_and(has_table_privilege('carrier_finance',t,'INSERT') and not has_table_privilege('carrier_finance',t,'UPDATE,DELETE')) from unnest(array['public.financial_events','public.journal_lines','public.allocations','public.idempotency_records','public.audit_events'])t),'Kernel appends without mutable financial rights');
select ok(not has_function_privilege('authenticated','private.post_claim_event(text,uuid,integer,jsonb)','EXECUTE') and not has_function_privilege('anon','private.claim_state(uuid)','EXECUTE'),'Private settlement/claim kernel is client inaccessible');
select ok((select bool_and(prosecdef and proconfig @> array['search_path=""']) from pg_proc where oid in ('private.post_claim_event(text,uuid,integer,jsonb)'::regprocedure,'private.claim_state(uuid)'::regprocedure,'public.post_financial_event(text,uuid,integer,jsonb)'::regprocedure,'public.get_trip_financials(uuid)'::regprocedure)),'Every definer has a pinned empty search path');
select ok(not has_table_privilege('carrier_security','public.financial_events','INSERT,UPDATE,DELETE'),'General command owner still cannot directly post money');
select ok(not has_function_privilege('anon','public.post_financial_event(text,uuid,integer,jsonb)','EXECUTE') and has_function_privilege('authenticated','public.post_financial_event(text,uuid,integer,jsonb)','EXECUTE'),'Receipt requires authenticated role');
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
select throws_ok($$select public.post_financial_event('CUSTOMER_RECEIPT',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','No live identity cannot post receipt');
select throws_ok($$select public.get_trip_financials(gen_random_uuid())$$,'42501','FORBIDDEN','No live identity cannot view claims');
select throws_ok($$select public.post_financial_event('OWNER_SETTLEMENT',gen_random_uuid(),0,'{}')$$,'22023','WORKFLOW_NOT_AVAILABLE','Client cannot bypass later settlement workflow');
reset role;
select * from finish();
rollback;
